<script setup>
import { onMounted, ref } from 'vue'
import { CreditCard, ListChecks, UserRound, X } from '@lucide/vue'
import api from '../api'
import LoadingSkeleton from './LoadingSkeleton.vue'
import { formatDateTime, money, orderLabels } from '../utils/format'
const props=defineProps({userId:{type:Number,required:true}}),emit=defineEmits(['close']),loading=ref(true),error=ref(''),data=ref(null)
onMounted(async()=>{try{data.value=await api.get(`/admin/users/${props.userId}`)}catch(e){error.value=e.message}finally{loading.value=false}})
</script>
<template><div class="modal-backdrop" @click.self="emit('close')"><section class="user-detail-dialog" role="dialog" aria-modal="true"><button class="icon-button light dialog-close" type="button" aria-label="关闭用户详情" @click="emit('close')"><X :size="19"/></button><LoadingSkeleton v-if="loading" :rows="2" compact/><div v-else-if="error" class="notice error">{{ error }}</div><template v-else><header><p class="eyebrow dark">USER PROFILE</p><h2><UserRound :size="22"/>{{ data.user.nickname || data.user.username }}</h2><span>@{{ data.user.username }} · {{ data.user.phone }}</span></header><dl class="user-metrics"><div><dt>订单总数</dt><dd>{{ data.orders.totalCount || 0 }}</dd></div><div><dt>已支付</dt><dd>{{ data.orders.paidCount || 0 }}</dd></div><div><dt>取消/超时</dt><dd>{{ data.orders.cancelledCount || 0 }}</dd></div><div><dt>当前消费</dt><dd>¥{{ money(data.orders.paidAmount) }}</dd></div><div><dt>成功支付</dt><dd>{{ data.payments.successCount || 0 }}</dd></div><div><dt>已退款</dt><dd>¥{{ money(data.payments.refundedAmount) }}</dd></div></dl><section><h3><ListChecks :size="18"/>最近订单</h3><div class="mini-records"><div v-for="order in data.orders.recent || []" :key="order.orderNo"><span class="mono">{{ order.orderNo }}</span><b>{{ orderLabels[order.status] || order.status }}</b><small>{{ formatDateTime(order.createdAt) }}</small></div></div></section><section><h3><CreditCard :size="18"/>最近支付</h3><div class="mini-records"><div v-for="payment in data.payments.recent || []" :key="payment.paymentNo"><span class="mono">{{ payment.paymentNo }}</span><b>{{ payment.status }}</b><small>¥{{ money(payment.amount) }}</small></div></div></section></template></section></div></template>
